INSERT INTO diadiem(TenDiaDiem,TinhThanh,MoTa,AnhDaiDien) VALUES
('Đà Lạt','Lâm Đồng','Thành phố ngàn hoa, rừng thông và khí hậu mát mẻ.','https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'),
('Ninh Bình','Ninh Bình','Non nước hữu tình và núi đá vôi.','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1000&q=85'),
('Hà Giang','Tuyên Quang','Cung đường vùng cao và bản làng.','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1000&q=85'),
('Phú Quốc','An Giang','Biển xanh, cát trắng và hoàng hôn.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1000&q=85');
INSERT INTO tours(MaDiaDiem,TenTour,MoTa,LichTrinh,SoNgay,SoDem,GiaTour,AnhDaiDien) VALUES
(1,'Đà Lạt — Chạm vào miền sương','Khám phá rừng thông, đồi chè và nhịp sống chậm của thành phố ngàn hoa.','Ngày 1: Đến Đà Lạt, tham quan trung tâm.\\nNgày 2: Đồi chè, rừng thông và cà phê địa phương.\\nNgày 3: Mua đặc sản, trở về.',3,2,2490000,'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'),
(2,'Ninh Bình — Miền di sản xanh','Chuyến đi chậm giữa núi đá vôi và dòng sông trong xanh.','Ngày 1: Tràng An và cố đô Hoa Lư.\\nNgày 2: Hang Múa và trở về.',2,1,1650000,'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1000&q=85'),
(3,'Hà Giang — Theo dấu mây trời','Cung đường vùng cao cho người yêu thiên nhiên và văn hoá bản địa.','Ngày 1: Hà Nội – Hà Giang.\\nNgày 2: Đồng Văn, đèo Mã Pí Lèng.\\nNgày 3: Thăm bản làng, trở về.',3,2,3290000,'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1000&q=85'),
(4,'Phú Quốc — Gọi nắng bên biển','Nghỉ dưỡng bên bờ biển, khám phá làng chài và ngắm hoàng hôn.','Ngày 1: Đến đảo và ngắm hoàng hôn.\\nNgày 2: Khám phá biển.\\nNgày 3: Nghỉ dưỡng.\\nNgày 4: Trở về.',4,3,4890000,'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1000&q=85'),
(1,'Cuối tuần giữa rừng thông','Kỳ nghỉ ngắn với cung đường xanh và không khí trong lành.','Ngày 1: Đồi thông và trung tâm.\\nNgày 2: Ăn sáng địa phương, trở về.',2,1,1790000,'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1000&q=85');
