CREATE DATABASE IF NOT EXISTS tourvela CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tourvela;
CREATE TABLE diadiem(MaDiaDiem INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,TenDiaDiem VARCHAR(120) NOT NULL,TinhThanh VARCHAR(100) NOT NULL,MoTa TEXT,AnhDaiDien VARCHAR(500)) ENGINE=InnoDB;
CREATE TABLE khachhang(MaKhachHang INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,HoTen VARCHAR(120) NOT NULL,Email VARCHAR(150) NOT NULL,SoDienThoai VARCHAR(30) NOT NULL,DiaChi VARCHAR(255),NgayTao DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(Email)) ENGINE=InnoDB;
CREATE TABLE tours(MaTour INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,MaDiaDiem INT UNSIGNED NOT NULL,TenTour VARCHAR(180) NOT NULL,MoTa TEXT,LichTrinh TEXT,SoNgay TINYINT UNSIGNED NOT NULL DEFAULT 3,SoDem TINYINT UNSIGNED NOT NULL DEFAULT 2,GiaTour DECIMAL(12,2) NOT NULL,SoChoCon INT UNSIGNED NOT NULL DEFAULT 20,AnhDaiDien VARCHAR(500),TrangThai ENUM('dang_mo','ngung') NOT NULL DEFAULT 'dang_mo',NgayTao DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(MaDiaDiem) REFERENCES diadiem(MaDiaDiem) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE dattour(MaDatTour INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,MaKhachHang INT UNSIGNED NOT NULL,MaTour INT UNSIGNED NOT NULL,NgayKhoiHanh DATE NOT NULL,SoNguoi INT UNSIGNED NOT NULL,GiaTaiThoiDiemDat DECIMAL(12,2) NOT NULL,TongTien DECIMAL(14,2) NOT NULL,TrangThai ENUM('cho_xac_nhan','da_xac_nhan','da_huy') DEFAULT 'cho_xac_nhan',GhiChu TEXT,NgayDat DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(MaKhachHang) REFERENCES khachhang(MaKhachHang),FOREIGN KEY(MaTour) REFERENCES tours(MaTour)) ENGINE=InnoDB;
CREATE TABLE lienhe(MaLienHe INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,HoTen VARCHAR(120) NOT NULL,Email VARCHAR(150) NOT NULL,NoiDung TEXT NOT NULL,NgayGui DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
